% initialize Fibonacci sequence with the first two numbers
fibonacci = [1, 1];

% loop to add the next number to the sequence by summing the two previous numbers
while fibonacci(end) < 1000
    next_fibonacci = fibonacci(end) + fibonacci(end-1);
    fibonacci = [fibonacci, next_fibonacci];
end

% initialize sum variable
sum_fibonacci = 0;

% loop to add each Fibonacci number less than 1000 to the sum variable
for I = 1:length(fibonacci)-1
    if fibonacci(i) < 1000
        sum_fibonacci = sum_fibonacci + fibonacci(i);
    else
        break;
    end
end

