Here is a sample C code that reads a binary file and calculates the checksum value:

```c
#include <stdio.h>

int main() {
    FILE *file;
    char filename[100];
    unsigned char byte;
    int sum = 0;

    // Prompt the user to enter the binary file name
    printf("Enter the name of the binary file: ");
    scanf("%s", filename);

    // Open the binary file in read mode
    file = fopen(filename, "rb");

    // Check if the file is opened successfully
    if (file == NULL) {
        printf("Error opening file.");
        return 1;
    }

    // Read the file byte by byte and calculate the checksum value
    while (fread(&byte, sizeof(unsigned char), 1, file) == 1) {
        sum += byte;
    }

    // Close the file
    fclose(file);

    // Print the checksum value
    printf("Checksum value: %d\n", sum);

    return 0;
}
```

In this code, we first prompt the user to enter the name of the binary file. We then open the file in read mode using the `fopen` function. If the file is opened successfully, we read the file byte by byte using the `fread` function and calculate the checksum value by adding up all the bytes. Finally, we close the file and print the checksum value.
